const D={"sc": {"s0": [1.3011977591349386, 0.4213370950905886], "m": [20.83342857142857, 5.0845714285714285, 171.48057142857144, 1.7424285714285714, 6.630257142857143], "sd": [1.747478907057892, 1.6296017793263706, 42.35094088635085, 0.6619860501643859, 1.219944468123907]}, "hist": [2, 39, 153, 136, 121, 163, 240, 463, 175, 147, 183, 247, 543, 210, 175, 182, 233, 429, 159, 104, 92, 136, 258, 122, 92, 74, 74, 37, 10, 1], "n": 5000, "mean": 6.23, "q": [5.1, 7.1], "r": -0.82, "usage": [["1\u20132h", 8.0, 117], ["2\u20133h", 8.02, 420], ["3\u20134h", 7.48, 862], ["4\u20135h", 6.55, 1031], ["5\u20136h", 5.81, 974], ["6\u20137h", 5.05, 822], ["7\u20138h", 4.91, 568], ["8h+", 5.07, 206]], "sleep": [["<5h", 5.13, 398], ["5h", 5.07, 1320], ["6h", 5.95, 1167], ["7h", 7.12, 1279], ["8h", 7.57, 735], ["9h+", 7.9, 101]], "stress": [["Low", 7.84, 644], ["Medium", 7.14, 1295], ["High", 6.03, 1440], ["Very High", 5.05, 1621]], "plat": [["LINE", 8.02, 50], ["VKontakte", 7.0, 40], ["WeChat", 6.49, 36], ["LinkedIn", 6.48, 523], ["Facebook", 6.4, 719], ["Twitter", 6.35, 462], ["YouTube", 6.22, 491], ["Instagram", 6.19, 1130], ["Snapchat", 6.12, 420], ["TikTok", 5.99, 918], ["KakaoTalk", 5.98, 36], ["WhatsApp", 5.58, 175]], "imp": [["Daily social media hours", 0.675], ["Sleep per night", 0.111], ["Phone unlocks per day", 0.047], ["Study hours", 0.027], ["Physical activity", 0.027], ["All other inputs", 0.112]]}, M={"n": 142276, "roots": [0, 3529, 7176, 10731, 14384, 17935, 21544, 25011, 28576, 32205, 35738, 39289, 42798, 46305, 49866, 53421, 56960, 60553, 64162, 67707, 71200, 74775, 78350, 81895, 85414, 89051, 92668, 96131, 99696, 103157, 106758, 110249, 113892, 117449, 120972, 124465, 128064, 131659, 135164, 138713], "b64": ""};
const $=id=>document.getElementById(id);
const C={gender:["Female","Male"],level:["Graduate","High School","Undergraduate"],plat:["Facebook","Instagram","KakaoTalk","LINE","LinkedIn","Snapchat","TikTok","Twitter","VKontakte","WeChat","WhatsApp","YouTube"],purpose:["Education","Entertainment","Networking","News"],country:["Australia","Canada","France","Germany","India","Mexico","Other","Turkey","UK","USA"]};
const bytes=Uint8Array.from(atob(M.b64),c=>c.charCodeAt(0)),n=M.n,buf=bytes.buffer;
const THR=new Float32Array(buf,0,n),L=new Int32Array(buf,4*n,n),R=new Int32Array(buf,8*n,n),F=new Int8Array(buf,12*n,n);
function forest(x){let s=0;for(const r of M.roots){let i=r;while(F[i]>=0)i=x[F[i]]<=THR[i]?L[i]:R[i];s+=THR[i]}return s/M.roots.length}
const S={stress:2};

function vec(s){const c=D.sc,x=new Array(38).fill(0);
x[0]=(Math.log1p(s.study)-c.s0[0])/c.s0[1];
["age","use","unl","phys","sleep"].forEach((k,i)=>x[1+i]=(s[k]-c.m[i])/c.sd[i]);
x[6]=s.stress;let o=7;
[["gender",2],["level",3],["plat",12],["purpose",4],["country",10]].forEach(([k,len])=>{x[o+C[k].indexOf(s[k])]=1;o+=len});
return x}

const state=()=>({use:+$("use").value,sleep:+$("sleep").value,unl:+$("unl").value,study:+$("study").value,phys:+$("phys").value,age:+$("age").value,stress:S.stress,gender:$("gender").value,level:$("level").value,plat:$("plat").value,purpose:$("purpose").value,country:$("country").value});
const pred=s=>forest(vec(s));

// ── Fill selects ──────────────────────────────────────────────────────────
const fill=(id,arr,def,lab)=>{$(id).innerHTML=arr.map(v=>`<option value="${v}"${v===def?" selected":""}>${lab&&lab[v]||v}</option>`).join("")};
fill("gender",C.gender,"Female");fill("level",C.level,"Undergraduate");fill("plat",C.plat,"Instagram");fill("purpose",C.purpose,"Entertainment");fill("country",C.country,"India",{Other:"Another country"});
["Low","Medium","High","Very High"].forEach((t,i)=>{const b=document.createElement("button");b.type="button";b.textContent=t;b.setAttribute("aria-pressed",i===S.stress);b.onclick=()=>{S.stress=i;[...$("stress").children].forEach((e,j)=>e.setAttribute("aria-pressed",j===i));run()};$("stress").appendChild(b)});

// ── Score ring ────────────────────────────────────────────────────────────
const CIRCUMFERENCE=326.7;
function updateRing(p){
  const arc=$("score-arc");
  if(!arc)return;
  const ratio=Math.min(1,Math.max(0,(p-1)/9));
  const offset=CIRCUMFERENCE-(ratio*CIRCUMFERENCE);
  arc.style.strokeDashoffset=offset;
  arc.style.stroke=p<D.q[0]?"var(--bad)":p>D.q[1]?"var(--good)":"var(--acc)";
}

// ── Histogram ─────────────────────────────────────────────────────────────
const H=D.hist,mx=Math.max(...H),X=v=>20+(v-3.5)/6*560,bw=560/H.length;
let hs="";H.forEach((h,i)=>{const lo=3.5+i*.2,mid=lo+.1,hh=h/mx*120;hs+=`<rect x="${20+i*bw+1}" y="${140-hh}" width="${bw-2}" height="${hh}" rx="3" fill="${mid<D.q[0]?"var(--bad2)":mid>D.q[1]?"var(--good2)":"var(--acc2)"}" stroke="${mid>=D.q[0]&&mid<=D.q[1]?"var(--acc3)":"var(--line)"}" stroke-width="0.5" opacity="${mid>=D.q[0]&&mid<=D.q[1]?1:.7}"/>`});
hs+=[4,5,6,7,8,9].map(v=>`<text x="${X(v)}" y="160" text-anchor="middle" font-size="12" fill="var(--mute)">${v}</text>`).join("");
hs+=`<g id="marker"><line x1="0" x2="0" y1="4" y2="140" stroke="var(--acc)" stroke-width="2.5"/><circle cx="0" cy="4" r="5" fill="var(--acc)"/><circle cx="0" cy="4" r="9" fill="var(--acc)" opacity=".18"/></g>`;
$("hist").innerHTML=hs;

function pct(v){const t=D.hist.reduce((a,b)=>a+b,0);let c=0;D.hist.forEach((h,i)=>{const lo=3.5+i*.2;if(v>=lo+.2)c+=h;else if(v>lo)c+=h*(v-lo)/.2});return Math.round(c/t*100)}

// ── Slider label update helpers ───────────────────────────────────────────
const names={use:"h",sleep:"h",unl:"",study:"h",phys:"h",age:""};
const fmt=(k,v)=>k==="unl"?Math.round(v):k==="age"?v:(+v).toFixed(1)+(names[k]||"");

// ── Main run ──────────────────────────────────────────────────────────────
function run(){
const s=state();
["use","sleep","unl","study","phys","age"].forEach(k=>{const o=$("o_"+k);if(o)o.textContent=fmt(k,s[k]);});
const p=pred(s);
$("num").textContent=p.toFixed(1);
updateRing(p);
const b=p<D.q[0]?["Below Typical","var(--bad)"]:p>D.q[1]?["Above Typical","var(--good)"]:["Typical","var(--acc)"];
$("band").textContent=b[0];$("band").style.color=b[1];
const q=pct(p);$("rank").textContent=`This score ranks higher than ${q}% of the ${D.n.toLocaleString()} students in the dataset. The dataset mean is ${D.mean}.`;
$("marker").setAttribute("transform",`translate(${X(Math.min(9.5,Math.max(3.5,p)))},0)`);
const T=[
  ["Reduce social media use by 1 hour",{use:Math.max(1,s.use-1)}],
  ["Sleep 1 additional hour per night",{sleep:Math.min(10,s.sleep+1)}],
  ["Add 30 minutes of physical activity",{phys:s.phys+.5}],
  ["Reduce phone unlocks by 30 per day",{unl:Math.max(50,s.unl-30)}],
  ["Increase study time by 1 hour",{study:s.study+1}],
  ["Lower perceived stress by one level",{stress:Math.max(0,s.stress-1)}]
];
const rows=T.map(([l,ch])=>[l,pred({...s,...ch})-p]);
$("deltas").innerHTML=rows.map(([l,d])=>{const w=Math.min(50,Math.abs(d)/1.5*50);return `<div class="d"><span>${l}</span><span class="t"><i style="${d>=0?"left:50%":"right:50%"};width:${w}%;background:${d>=0?"var(--good)":"var(--bad)"}"></i></span><b style="color:${d>=0?"var(--good)":"var(--bad)"}">${d>=0?"+":"−"}${Math.abs(d).toFixed(2)}</b></div>`}).join("")}
document.querySelectorAll("input,select").forEach(e=>e.addEventListener("input",run));

// ── Insight charts ────────────────────────────────────────────────────────
function line(id,pts){const W=480,Ht=220,l=36,r=12,t=14,bm=30,lo=4,hi=9,x=i=>l+i*(W-l-r)/(pts.length-1),y=v=>t+(hi-v)/(hi-lo)*(Ht-t-bm);
let s=[4,5,6,7,8,9].map(v=>`<line x1="${l}" x2="${W-r}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${l-6}" y="${y(v)+4}" text-anchor="end" font-size="11" fill="var(--mute)">${v}</text>`).join("");
s+=`<polyline fill="none" stroke="var(--acc)" stroke-width="2.5" stroke-linejoin="round" points="${pts.map((p,i)=>x(i)+","+y(p[1])).join(" ")}"/>`;
s+=pts.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p[1])}" r="4.5" fill="var(--acc)"><title>${p[0]}: ${p[1]} (${p[2]} students)</title></circle><text x="${x(i)}" y="${Ht-8}" text-anchor="middle" font-size="11" fill="var(--mute)">${p[0]}</text>`).join("");
const e=$(id);e.setAttribute("viewBox",`0 0 ${W} ${Ht}`);e.innerHTML=s}
function bars(id,rows,lo,hi){$(id).innerHTML=rows.map(r=>`<div class="br"><span style="background:none;height:auto;color:var(--ink);font-weight:500">${r[0]}</span><span style="width:${(r[1]-lo)/(hi-lo)*100}%"></span><em>${r[1].toFixed(1)}</em></div>`).join("")}
line("c_use",D.usage);line("c_sleep",D.sleep);
bars("c_stress",D.stress,0,9);bars("c_plat",D.plat.filter(r=>r[2]>=100),0,9);
$("rv").textContent=D.r;
$("imp").innerHTML=D.imp.map(r=>`<div class="br" style="grid-template-columns:160px minmax(0,1fr) 44px"><span style="background:none;height:auto;color:var(--ink);font-weight:500">${r[0]}</span><span style="width:${r[1]/D.imp[0][1]*100}%"></span><em>${Math.round(r[1]*100)}%</em></div>`).join("");

// ── Scroll-reveal observer ────────────────────────────────────────────────
// Mark js-ready AFTER all content is rendered so the observer fires correctly
document.documentElement.classList.add("js-ready");
const obs=new IntersectionObserver(entries=>{
  entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add("visible");obs.unobserve(e.target);}});
},{threshold:0.05,rootMargin:"0px 0px -20px 0px"});
// Observe and immediately resolve anything already in view
document.querySelectorAll(".animate-on-scroll").forEach(el=>{
  const r=el.getBoundingClientRect();
  if(r.top<window.innerHeight&&r.bottom>0){el.classList.add("visible");}
  else{obs.observe(el);}
});

run();
